      if (!automatingNow()) return orig.apply(this, arguments);
      const now = Date.now();
      if (now - lastJump < GAP) return;
      lastJump = now;
      if (a && typeof a === 'object') return orig.call(this, Object.assign({}, a, { behavior: 'instant' }));
      return orig.apply(this, arguments);
