    if (x === y) return 1;
    if (y.startsWith(x) || x.startsWith(y)) return 0.92;
    if (y.includes(x) || x.includes(y)) return 0.85;
    const tx = new Set(x.split(' ')), ty = new Set(y.split(' '));
